const { MongoClient } = require('mongodb');

// Connect to MongoDB
const url = 'mongodb://localhost:27017'; // MongoDB URI
const dbName = 'prs-pandemic-db';  // Database Name
const client = new MongoClient(url, { useNewUrlParser: true, useUnifiedTopology: true });

const saveMetadataToDatabase = async (fileUrl, userId) => {
  try {
    await client.connect();
    const db = client.db(dbName);
    const collection = db.collection('file_metadata');

    const metadata = {
      user_id: userId,
      file_name: 'certificate_12345.pdf',  // Example file name
      file_url: fileUrl,
      file_status: 'Pending',
      upload_timestamp: new Date(),
    };

    const result = await collection.insertOne(metadata);
    console.log('Metadata saved:', result.ops[0]);
  } catch (err) {
    console.error('Error saving metadata:', err);
  } finally {
    await client.close();
  }
};
```

